UPDATE t_p52389855_chess_online_platfor.rating_settings
SET value = 'Рейтинг определяется на основе результатов партий. За победу начисляются баллы, за поражение — снимаются. Ничья дает небольшой бонус обоим игрокам. Ежедневно рейтинг всех игроков снижается на фиксированное значение для стимуляции активной игры. Рейтинг не может опускаться ниже минимального порога — даже при ежедневном снижении. Начисление баллов рейтинга происходит одинаковым образом ко всем типам игры в шахматы (блиц, рапид, классика и др.). Серия побед: если игрок в режиме «Играть онлайн» побеждает три партии подряд с тремя разными соперниками (живыми игроками или ботами), ему начисляется дополнительный бонус +25 к рейтингу. После начисления бонуса счётчик серии сбрасывается.'
WHERE key = 'rating_principles';